"use strict";
(()=>{
const D=window.stopResearch,R=D.report,$=s=>document.querySelector(s);
const pct=x=>x==null?'—':(x>0?'+':'')+(x*100).toFixed(2)+'%',win=x=>x==null?'—':(x*100).toFixed(2)+'%',ratio=x=>x==null?'—':x.toFixed(2),day=x=>x?String(x).replace(/(\d{4})(\d{2})(\d{2})/,'$1-$2-$3'):'—',money=x=>Number(x).toFixed(2);
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={original:'历史原参数，不止损',uncapped:'取消涨幅上限，不止损',uncapped_stop:'新规则：取消上限＋分级止损',original_stop:'辅助：原上限＋分级止损'};
const reasons={half_intraday:'盘中跌破中点，减半',half_gap:'低开跌破中点，减半',half_queued:'已触发减半，最早可卖日开盘',full_intraday:'盘中跌破前收，清仓',full_gap:'低开跌破前收，清仓',full_queued:'已触发清仓，最早可卖日开盘',expiry:'持有期届满，收盘退出',expiry_delayed:'到期无法卖出，顺延开盘'};
let strategy='balanced',page=0,visible=[],cleanup=null,opener=null;const size=15;
function render(){const s=R.strategies[strategy],v=s.variants.uncapped_stop,t=v.trade_stats;
document.querySelectorAll('[data-strategy]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.strategy===strategy)));
$('#strategy-caption').textContent=(strategy==='balanced'?'量能＋周线平衡版':'量能＋MACD排序版')+' · 当前指标：取消涨幅上限＋分级止损 · 剩余仓位最长计划持有 '+s.hold+' 个市场交易日，含买入日';
$('#stops-stats').innerHTML=[['组合年化',pct(v.cagr),'累计净收益 '+pct(v.total)],['最大回撤',pct(v.max_drawdown),'每日收盘权益'],['成交胜率',win(t.win),v.fills+' 笔 · '+v.active_entry_dates+' 个买入日'],['盈亏比',ratio(t.payoff),'单笔平均净收益 '+pct(t.mean)]].map(([a,b,c])=>`<article><div><h2>${a}</h2><strong>${b}</strong><p>${c}</p></div></article>`).join('');
$('#variant-comparison').innerHTML=['original','uncapped','uncapped_stop','original_stop'].map(key=>{const a=s.variants[key],q=a.trade_stats;return `<tr class="${key==='uncapped_stop'?'current-variant':''}"><td>${names[key]}</td><td>${pct(a.cagr)}</td><td>${pct(a.max_drawdown)}</td><td>${win(q.win)}</td><td>${ratio(q.payoff)}</td><td>${pct(q.mean)}</td><td>${pct(q.worst)}</td><td>${a.fills}</td></tr>`}).join('');
const m=s.fixed_entries;$('#matched-comparison').innerHTML=[['同批入场，原平均净收益',pct(m.before.mean),m.before.n+' 笔固定入场'],['改成分级止损后',pct(m.after.mean),'平均变化 '+(m.mean_delta*100).toFixed(2)+' 个百分点'],['逐笔改善 / 变差',m.improved+' / '+m.worsened,m.unchanged+' 笔基本不变']].map(([a,b,c])=>`<article><p>${a}</p><strong>${b}</strong><p>${c}</p></article>`).join('');
$('#exit-counts').textContent=`新规则共 ${v.fills} 笔成交：${v.half_reductions} 笔发生减半卖出，${v.full_stops} 笔发生清仓止损；${v.entry_day_breaches} 笔在买入日已触发、因T+1延后执行，${v.blocked_trades} 笔遇封死跌停延迟。减半与清仓统计可重叠；平均仓位 ${win(v.average_exposure)}。`;
$('#annual-stops').innerHTML=v.annual.map((a,i)=>{const q=v.annual_trade_stats.find(x=>x.year===2022+i)||{};return `<tr><td>${2022+i}${i===4?'（截至快照）':''}</td><td>${pct(s.variants.uncapped.annual[i])}</td><td>${pct(a)}</td><td>${pct(v.annual_drawdown[i])}</td><td>${q.n||0}</td><td>${win(q.win)}</td></tr>`}).join('');
$('#entry-rules').textContent=strategy==='balanced'?'前60日最低收盘价L；前250日起至L的最高收盘价到L跌幅至少30%。L距信号最多15日，前一日不超过1.12×L。前40日阳线日均量/阴线日均量≥1，各至少3根。已完成周K涨跌幅好于前一周；市场当日等权涨幅≥1.5%。同日按近20日均成交额排序。':'前60日最低收盘价L；前120日起至L的最高收盘价到L跌幅至少30%。L距信号最多8日，前一日不超过1.08×L。市场当日等权涨幅≥2%。按clip(ln(40日阳阴均量比),-1,1)＋近似双底MACD背离分1＋MACD柱连续两次回升分0.5排序；同分按成交额排序。低点左右各2根确认，且必须在信号前完成。';
chart();filter();}
function chart(){const canvas=$('#equity-chart'),w=canvas.clientWidth,h=canvas.clientHeight,dpr=Math.min(devicePixelRatio||1,2);if(w<100)return;canvas.width=w*dpr;canvas.height=h*dpr;const c=canvas.getContext('2d');c.scale(dpr,dpr);const sets=[['uncapped','#8b82b8'],['uncapped_stop','#c47a26']],a=D.curves[strategy],all=sets.flatMap(([key])=>a[key].map(x=>x[1])),lo=Math.min(.9,...all)*.98,hi=Math.max(...all)*1.05,left=52,right=w-16,top=18,bottom=h-28,x=i=>left+i/(a.uncapped.length-1)*(right-left),y=v=>top+(hi-v)/(hi-lo)*(bottom-top);c.font='11px system-ui';for(let i=0;i<5;i++){const value=lo+(hi-lo)*i/4,py=y(value);c.strokeStyle='#e8e8f2';c.beginPath();c.moveTo(left,py);c.lineTo(right,py);c.stroke();c.fillStyle='#777f94';c.fillText(value.toFixed(2),5,py+4)}for(const [key,color] of sets){c.strokeStyle=color;c.lineWidth=2;c.beginPath();a[key].forEach((v,i)=>i?c.lineTo(x(i),y(v[1])):c.moveTo(x(i),y(v[1])));c.stroke()}let last=0;a.uncapped.forEach((v,i)=>{const year=Math.floor(v[0]/10000);if(year!==last){last=year;c.fillStyle='#737c93';c.fillText(year,x(i),h-6)}})}
function filter(){const version=$('#trade-version').value,q=$('#trade-search').value.trim().toLowerCase(),kind=$('#exit-filter').value,sort=$('#trade-sort').value;visible=D.rows[strategy][version].filter(x=>(!q||(x.name+x.code).toLowerCase().includes(q))&&(kind==='all'||kind==='half'&&x.half_sell_date>0||kind==='full'&&x.full_stop_date>0||kind==='t1'&&x.stop_enabled&&x.entry_day_breach>0));visible.sort((a,b)=>sort==='worst'?a.net-b.net:sort==='best'?b.net-a.net:b.signal_date-a.signal_date||a.code.localeCompare(b.code));page=0;$('#download-trades').href='stops-'+strategy+'_'+version+'.csv';table()}
function table(){const a=visible.slice(page*size,(page+1)*size);$('#trade-rows').innerHTML=a.length?a.map(x=>`<tr><td><button class="research-stock" data-event="${x.event_id}"><strong>${esc(x.name)}</strong><small>${esc(x.code)} · ${day(x.signal_date)}</small></button></td><td>${money(x.buy_price)}</td><td>${money(x.stop_half_price)}<small>${pct(x.stop_half_distance)}</small></td><td>${money(x.stop_full_price)}<small>${pct(x.stop_full_distance)}</small></td><td>${day(x.half_sell_date)}</td><td>${day(x.full_stop_date)}</td><td>${day(x.exit_date)}</td><td class="${x.net>0?'gain':'loss'}">${pct(x.net)}</td></tr>`).join(''):'<tr><td colspan="8">没有符合条件的交易</td></tr>';$('#trade-count').textContent=`共 ${visible.length} 条 · 第 ${page+1} / ${Math.max(1,Math.ceil(visible.length/size))} 页`;$('#prev-page').disabled=page===0;$('#next-page').disabled=(page+1)*size>=visible.length}
document.querySelectorAll('[data-strategy]').forEach(b=>b.addEventListener('click',()=>{strategy=b.dataset.strategy;render()}));for(const id of ['trade-version','exit-filter','trade-sort'])$('#'+id).addEventListener('change',filter);$('#trade-search').addEventListener('input',filter);$('#prev-page').addEventListener('click',()=>{page--;table()});$('#next-page').addEventListener('click',()=>{page++;table()});
const dialog=$('#research-detail');$('#trade-rows').addEventListener('click',ev=>{const b=ev.target.closest('[data-event]');if(!b)return;opener=b;const x=visible.find(x=>x.event_id===Number(b.dataset.event));$('#detail-name').textContent=x.name;$('#detail-subtitle').textContent=x.code+' · 信号 '+day(x.signal_date)+' · '+names[$('#trade-version').value];$('#detail-metrics').innerHTML=[['买入价（当日未复权）',money(x.buy_price),day(x.entry_date)+' · '+x.quantity+'股'],['最终净收益',pct(x.net),'最后卖出 '+day(x.exit_date)],['减半线（信号基准）',money(x.stop_half_price),'距买价 '+pct(x.stop_half_distance)],['清仓线（信号基准）',money(x.stop_full_price),'距买价 '+pct(x.stop_full_distance)]].map(([a,b,c])=>`<div><span>${a}</span><b>${b}</b><small>${c}</small></div>`).join('');$('#detail-rule').textContent=`信号涨幅 ${pct(x.signal_return)}，量为此前5日的 ${x.volume5.toFixed(2)} 倍、10日的 ${x.volume10.toFixed(2)} 倍；市场当日 ${pct(x.market_day)}、近20日 ${pct(x.market20)}。${x.stop_enabled?'橙色虚线为减半线，红色虚线为清仓线。':'本条为不止损对照，不执行两条止损线。'}${x.entry_day_breach&&x.stop_enabled?' 买入日已触发止损，T+1后执行。':''}${x.half_skipped_lot?' 初始仅100股，跳过半仓卖出。':''}`;$('#sale-rows').innerHTML=x.actions.map(a=>`<tr><td>${day(a.date)}</td><td>${a.quantity}股 / ${win(a.fraction)}</td><td>${money(a.raw_price)}</td><td>${reasons[a.reason]||esc(a.reason)}</td></tr>`).join('');if(cleanup)cleanup();const root=dialog.querySelector('.candle-panel');root.querySelector('canvas').hidden=false;dialog.showModal();cleanup=window.mountSignalCandles(root,x,null)});
$('#close-detail').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>{if(cleanup)cleanup();cleanup=null;opener?.focus()});dialog.addEventListener('click',ev=>{if(ev.target===dialog){const a=dialog.getBoundingClientRect();if(ev.clientX<a.left||ev.clientX>a.right||ev.clientY<a.top||ev.clientY>a.bottom)dialog.close()}});new ResizeObserver(chart).observe($('#equity-chart'));render();
})();
